"""Immutable file handoff for images generated by an interactive Codex session.

The pipeline holds the run lock when preparing work. A separate operator can
inspect the frozen request, generate an image, then import the result while
holding that same run lock. This module does not invoke any image provider.
"""

from __future__ import annotations

import hashlib
import io
import json
import os
import re
import shutil
import tempfile
import warnings
from contextlib import contextmanager
from pathlib import Path, PurePosixPath, PureWindowsPath
from typing import Any

from filelock import FileLock, Timeout
from PIL import Image, ImageOps, UnidentifiedImageError

from ..storage import RunLock, atomic_publish, fingerprint, write_json

_ID = re.compile(r"[A-Za-z0-9_-]{1,128}\Z")
_HASH = re.compile(r"[0-9a-f]{64}\Z")
_IMAGE_EXT = {"PNG": ".png", "JPEG": ".jpg", "WEBP": ".webp"}
_MAX_IMAGE_BYTES = 20 * 1024 * 1024
_MAX_TOTAL_REFERENCE_BYTES = 50 * 1024 * 1024
_MAX_IMAGE_PIXELS = 40_000_000
_MAX_REFERENCES = 10


class ImageTaskPending(RuntimeError):
    """The request is ready for an external image-generation operator."""

    def __init__(self, task_id: str):
        self.task_id = task_id
        super().__init__(f"Image task {task_id} awaits Codex image generation")


def _key_prefix(key: str) -> str:
    if not isinstance(key, str) or not key.strip():
        raise ValueError("Image task key must be a nonempty string")
    if _ID.fullmatch(key) and len(key) <= 80:
        return key
    return "image_" + hashlib.sha256(key.encode("utf-8")).hexdigest()[:32]


def _task_id(body: dict) -> str:
    """Bind the visible ID to the entire request, independently of its own hash."""
    material = {key: value for key, value in body.items() if key not in {"task_id", "task_sha256"}}
    return _key_prefix(material["key"]) + "_" + fingerprint(material)[:32]


def _check_id(task_id: str) -> str:
    if not isinstance(task_id, str) or not _ID.fullmatch(task_id):
        raise ValueError("Invalid image task ID")
    return task_id


def _run_root(run: Path) -> Path:
    raw = Path(run).expanduser()
    if raw.is_symlink() or not raw.is_dir():
        raise ValueError("Image task run must be an existing non-symlink directory")
    return raw.resolve(strict=True)


def _within(root: Path, *parts: str, must_exist: bool = False) -> Path:
    """Reject symlink components and paths escaping the already-resolved root."""
    if root.is_symlink():
        raise ValueError("Image task paths cannot contain symbolic links")
    path = root
    for part in parts:
        posix = PurePosixPath(part)
        windows = PureWindowsPath(part)
        if (
            not part
            or posix.is_absolute()
            or windows.is_absolute()
            or windows.drive
            or ".." in posix.parts
            or ".." in windows.parts
            or "\\" in part
        ):
            raise ValueError("Image task path must remain inside its directory")
        for component in posix.parts:
            path = path / component
            if path.is_symlink():
                raise ValueError("Image task paths cannot contain symbolic links")
    if not path.resolve().is_relative_to(root):
        raise ValueError("Image task path escapes its run")
    if must_exist and not path.exists():
        raise ValueError("Image task file is missing")
    return path


def _tasks_root(run: Path, *, create: bool) -> Path:
    root = _within(run, "image_tasks")
    if create:
        root.mkdir(exist_ok=True)
        root = _within(run, "image_tasks", must_exist=True)
    elif not root.exists():
        return root
    if not root.is_dir():
        raise ValueError("Image task storage must be a directory")
    return root


@contextmanager
def _task_lock(root: Path, task_id: str):
    path = _within(root, f".{_check_id(task_id)}.lock")
    lock = FileLock(str(path), timeout=30)
    try:
        lock.acquire()
    except Timeout:
        raise RuntimeError(f"Image task is locked: {task_id}") from None
    try:
        _within(root, path.name, must_exist=True)
        yield
    finally:
        lock.release()


def _read_file(path: Path, limit: int) -> bytes:
    if path.is_symlink() or not path.is_file():
        raise ValueError("Image input must be an existing non-symlink file")
    with path.open("rb") as stream:
        data = stream.read(limit + 1)
    if len(data) > limit:
        raise ValueError("Image exceeds the per-file size limit")
    return data


def _image_info(data: bytes) -> tuple[str, int, int]:
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with Image.open(io.BytesIO(data)) as image:
                image_format = image.format
                if image_format not in _IMAGE_EXT:
                    raise ValueError("Image must be PNG, JPEG, or WebP")
                width, height = image.size
                if width <= 0 or height <= 0 or width * height > _MAX_IMAGE_PIXELS:
                    raise ValueError("Image dimensions exceed the pixel limit")
                if getattr(image, "n_frames", 1) != 1:
                    raise ValueError("Animated images are not supported")
                image.verify()
            with Image.open(io.BytesIO(data)) as image:
                image.load()
    except (
        UnidentifiedImageError,
        OSError,
        SyntaxError,
        Image.DecompressionBombError,
        Image.DecompressionBombWarning,
    ) as exc:
        raise ValueError("Image cannot be safely decoded") from exc
    return image_format, width, height


def _load_json(path: Path) -> dict[str, Any]:
    if path.is_symlink() or not path.is_file():
        raise ValueError("Image task metadata is missing or a symbolic link")
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("Image task metadata cannot be read") from exc
    if not isinstance(value, dict):
        raise ValueError("Image task metadata must be an object")
    return value


def _write_bytes(path: Path, data: bytes) -> None:
    if path.is_symlink():
        raise ValueError("Image task output cannot be a symbolic link")
    fd, temporary = tempfile.mkstemp(prefix=".image-", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(data)
        if path.is_symlink():
            raise ValueError("Image task output cannot be a symbolic link")
        atomic_publish(Path(temporary), path)
    finally:
        Path(temporary).unlink(missing_ok=True)


def _request_body(
    key: str,
    *,
    prompt: str,
    prompt_version: str,
    kind: str,
    width: int,
    height: int,
    references: list[dict] | None,
    context: dict | None,
) -> tuple[dict, list[bytes]]:
    _key_prefix(key)
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError("Image task prompt must be nonempty")
    if not isinstance(prompt_version, str) or not prompt_version.strip():
        raise ValueError("Image task prompt version must be nonempty")
    if kind not in {"character", "scene", "prop", "frame"}:
        raise ValueError("Unknown image task kind")
    if any(type(value) is not int or value <= 0 for value in (width, height)):
        raise ValueError("Image task dimensions must be positive integers")
    if context is None:
        context = {}
    if not isinstance(context, dict):
        raise ValueError("Image task context must be an object")
    if references is None:
        references = []
    if not isinstance(references, list) or len(references) > _MAX_REFERENCES:
        raise ValueError(f"Image tasks accept up to {_MAX_REFERENCES} references")
    mode = context.get("mode", "edit" if references else "generate")
    if mode not in {"generate", "edit"} or (mode == "edit" and not references):
        raise ValueError("Image task mode must be generate, or edit with a reference")

    items, contents = [], []
    total = 0
    for index, ref in enumerate(references, 1):
        if not isinstance(ref, dict) or not isinstance(ref.get("path"), (str, Path)):
            raise ValueError("Each image reference needs a local path")
        role = ref.get("role")
        if not isinstance(role, str) or not role.strip():
            raise ValueError("Each image reference needs a role")
        data = _read_file(Path(ref["path"]).expanduser(), _MAX_IMAGE_BYTES)
        total += len(data)
        if total > _MAX_TOTAL_REFERENCE_BYTES:
            raise ValueError("Image references exceed the combined size limit")
        image_format, _, _ = _image_info(data)
        digest = hashlib.sha256(data).hexdigest()
        if ref.get("sha256") is not None and ref["sha256"] != digest:
            raise ValueError("Image reference content does not match its expected hash")
        items.append(
            {
                "path": f"references/{index:02d}{_IMAGE_EXT[image_format]}",
                "role": role,
                "sha256": digest,
            }
        )
        contents.append(data)
    body = {
        "schema_version": 1,
        "key": key,
        "prompt": prompt,
        "prompt_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
        "prompt_version": prompt_version,
        "kind": kind,
        "mode": mode,
        "width": width,
        "height": height,
        "references": items,
        "context": context,
    }
    # Force JSON serialization now, before staging any task files.
    body["task_id"] = _task_id(body)
    return body, contents


def _verify_request(run: Path, task_id: str) -> tuple[Path, dict, list[Path]]:
    root = _tasks_root(run, create=False)
    directory = _within(root, _check_id(task_id), must_exist=True)
    if not directory.is_dir():
        raise ValueError("Image task is not a directory")
    request = _load_json(_within(directory, "request.json", must_exist=True))
    expected_fields = {
        "schema_version",
        "task_id",
        "key",
        "prompt",
        "prompt_sha256",
        "prompt_version",
        "kind",
        "mode",
        "width",
        "height",
        "references",
        "context",
        "task_sha256",
    }
    if set(request) != expected_fields or request.get("schema_version") != 1:
        raise ValueError("Invalid image task request fields")
    body = {name: value for name, value in request.items() if name != "task_sha256"}
    if request["task_id"] != task_id or _task_id(body) != task_id:
        raise ValueError("Image task identity does not match its directory")
    if not isinstance(request["task_sha256"], str) or fingerprint(body) != request["task_sha256"]:
        raise ValueError("Image task request fingerprint does not match")
    prompt = request["prompt"]
    if (
        not isinstance(prompt, str)
        or not prompt.strip()
        or hashlib.sha256(prompt.encode("utf-8")).hexdigest() != request["prompt_sha256"]
    ):
        raise ValueError("Image task prompt fingerprint does not match")
    prompt_file = _within(directory, "prompt.txt", must_exist=True)
    if not prompt_file.is_file() or prompt_file.read_bytes() != prompt.encode("utf-8"):
        raise ValueError("Image task prompt file was changed")
    refs = request["references"]
    if not isinstance(refs, list) or len(refs) > _MAX_REFERENCES:
        raise ValueError("Invalid image task references")
    if (
        request["kind"] not in {"character", "scene", "prop", "frame"}
        or request["mode"] not in {"generate", "edit"}
        or (request["mode"] == "edit" and not refs)
        or not isinstance(request["context"], dict)
        or not isinstance(request["prompt_version"], str)
        or not request["prompt_version"].strip()
        or any(type(request[n]) is not int or request[n] <= 0 for n in ("width", "height"))
    ):
        raise ValueError("Invalid image task request values")
    paths = []
    total = 0
    for index, ref in enumerate(refs, 1):
        if (
            not isinstance(ref, dict)
            or set(ref) != {"path", "role", "sha256"}
            or not isinstance(ref["path"], str)
            or not isinstance(ref["role"], str)
            or not ref["role"].strip()
            or not isinstance(ref["sha256"], str)
            or not _HASH.fullmatch(ref["sha256"])
        ):
            raise ValueError("Invalid image task reference metadata")
        path = _within(directory, ref["path"], must_exist=True)
        data = _read_file(path, _MAX_IMAGE_BYTES)
        total += len(data)
        if total > _MAX_TOTAL_REFERENCE_BYTES:
            raise ValueError("Image references exceed the combined size limit")
        image_format, _, _ = _image_info(data)
        expected = f"references/{index:02d}{_IMAGE_EXT[image_format]}"
        if ref["path"] != expected or hashlib.sha256(data).hexdigest() != ref["sha256"]:
            raise ValueError("Image task reference was changed")
        paths.append(path)
    return directory, request, paths


def _main_region(bounds: Any, data: bytes) -> dict:
    """Validate half-open bounds against the image's displayed orientation."""
    if not isinstance(bounds, (list, tuple)) or len(bounds) != 4:
        raise ValueError("Main region must contain four integer pixel bounds")
    if any(type(value) is not int for value in bounds):
        raise ValueError("Main region must contain four integer pixel bounds")
    with Image.open(io.BytesIO(data)) as image:
        oriented = ImageOps.exif_transpose(image)
        try:
            width, height = oriented.size
        finally:
            oriented.close()
    left, top, right, bottom = bounds
    if not (0 <= left < right <= width and 0 <= top < bottom <= height):
        raise ValueError("Main region must be nonempty and inside the displayed image")
    return {"bounds": list(bounds), "width": width, "height": height}


def _verify_result(directory: Path, request: dict) -> tuple[dict | None, Path | None]:
    result_path = _within(directory, "result.json")
    if not result_path.exists():
        return None, None
    result = _load_json(result_path)
    expected_fields = {
        "schema_version",
        "status",
        "task_sha256",
        "path",
        "sha256",
        "format",
        "width",
        "height",
        "notes",
        "review_accepted",
    }
    if (
        set(result) not in (expected_fields, expected_fields | {"main_region"})
        or result["schema_version"] != 1
        or result["status"] != "completed"
        or result["review_accepted"] is not True
        or result["task_sha256"] != request["task_sha256"]
        or not isinstance(result["sha256"], str)
        or not _HASH.fullmatch(result["sha256"])
        or not isinstance(result["notes"], str)
        or not result["notes"].strip()
        or not isinstance(result["path"], str)
    ):
        raise ValueError("Invalid image task result metadata")
    path = _within(directory, result["path"], must_exist=True)
    data = _read_file(path, _MAX_IMAGE_BYTES)
    image_format, width, height = _image_info(data)
    if (
        result["path"] != f"results/{result['sha256']}{_IMAGE_EXT[image_format]}"
        or hashlib.sha256(data).hexdigest() != result["sha256"]
        or result["format"] != image_format
        or type(result["width"]) is not int
        or type(result["height"]) is not int
        or result["width"] != width
        or result["height"] != height
    ):
        raise ValueError("Image task result was changed")
    if "main_region" in result:
        region = result["main_region"]
        if (
            not isinstance(region, dict)
            or set(region) != {"bounds", "width", "height"}
            or type(region["width"]) is not int
            or type(region["height"]) is not int
        ):
            raise ValueError("Invalid image task main region")
        if _main_region(region["bounds"], data) != region:
            raise ValueError("Image task main region does not match the displayed image")
        if request["kind"] not in {"scene", "prop"}:
            raise ValueError("Main region is only supported for scene and prop tasks")
    return result, path


def _describe(run: Path, task_id: str) -> dict:
    directory, request, refs = _verify_request(run, task_id)
    result, result_file = _verify_result(directory, request)
    return {
        "task_id": task_id,
        "status": "completed" if result else "pending",
        "task_directory": str(directory),
        "prompt_file": str(directory / "prompt.txt"),
        "reference_files": [str(path) for path in refs],
        "result_file": str(result_file) if result_file else None,
        "request": request,
        "result": result,
    }


def prepare_image_task(
    run: Path,
    key: str,
    *,
    prompt: str,
    prompt_version: str,
    kind: str,
    width: int,
    height: int,
    references: list[dict] | None = None,
    context: dict | None = None,
) -> list[str]:
    """Freeze a request and pause, or return its already-imported result.

    The caller serializes run mutations with RunLock. This function deliberately
    does not acquire RunLock again, because the pipeline holds it on resume.
    """
    root = _run_root(run)
    tasks_root = _tasks_root(root, create=True)
    body, contents = _request_body(
        key,
        prompt=prompt,
        prompt_version=prompt_version,
        kind=kind,
        width=width,
        height=height,
        references=references,
        context=context,
    )
    task_id = body["task_id"]
    request = {**body, "task_sha256": fingerprint(body)}
    prefix = _key_prefix(key)
    with _task_lock(tasks_root, prefix):
        # Serialize all request revisions for the same logical key. Never make
        # a new task ID silently replace an earlier request with altered inputs.
        for entry in tasks_root.iterdir():
            if (
                len(entry.name) != len(prefix) + 33
                or not entry.name.startswith(prefix + "_")
                or not re.fullmatch(r"[0-9a-f]{32}", entry.name[-32:])
            ):
                continue
            if entry.is_symlink() or not entry.is_dir():
                raise ValueError("Image task storage contains an invalid task directory")
            _, previous, _ = _verify_request(root, entry.name)
            if previous["key"] == key and entry.name != task_id:
                raise ValueError("Image task inputs changed; create a new run")
        directory = _within(tasks_root, task_id)
        if directory.exists():
            _, previous, _ = _verify_request(root, task_id)
            if previous != request:
                raise ValueError("Image task inputs changed; create a new run")
        else:
            created = Path(tempfile.mkdtemp(prefix=".staging-", dir=tasks_root))
            staging = _within(tasks_root, created.name, must_exist=True)
            try:
                (staging / "prompt.txt").write_bytes(prompt.encode("utf-8"))
                for item, data in zip(body["references"], contents, strict=True):
                    destination = _within(staging, item["path"])
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    destination.write_bytes(data)
                write_json(staging / "request.json", request)
                _within(tasks_root, task_id)
                atomic_publish(staging, directory)
            finally:
                if staging.exists() and not staging.is_symlink():
                    verified = _within(tasks_root, staging.name, must_exist=True)
                    if not verified.name.startswith(".staging-"):
                        raise ValueError("Invalid temporary image task directory")
                    shutil.rmtree(verified)
        description = _describe(root, task_id)
        if description["result_file"]:
            return [description["result_file"]]
    raise ImageTaskPending(task_id)


def get_image_task(run: Path, task_id: str) -> dict:
    """Return a verified request and any verified result for an operator."""
    return _describe(_run_root(run), _check_id(task_id))


def list_image_tasks(run: Path) -> list[dict]:
    """List complete requests, ignoring temporary files and lock markers."""
    root = _run_root(run)
    tasks_root = _tasks_root(root, create=False)
    if not tasks_root.exists():
        return []
    result = []
    for path in sorted(tasks_root.iterdir()):
        if path.name.startswith("."):
            continue
        if path.is_symlink():
            raise ValueError("Image task storage cannot contain symbolic links")
        if path.is_dir():
            result.append(_describe(root, _check_id(path.name)))
    return result


def complete_image_task(
    run: Path,
    task_id: str,
    image: Path,
    *,
    notes: str,
    accepted: bool = False,
    main_region: list[int] | tuple[int, int, int, int] | None = None,
) -> dict:
    """Copy an explicitly accepted candidate; never overwrite another result."""
    if accepted is not True:
        raise ValueError("Image task completion requires explicit visual acceptance")
    if not isinstance(notes, str) or not notes.strip():
        raise ValueError("Image task completion requires visual inspection notes")
    task_id = _check_id(task_id)
    root = _run_root(run)
    with RunLock(root):
        tasks_root = _tasks_root(root, create=False)
        if not tasks_root.is_dir():
            raise ValueError("Image task does not exist")
        _, initial_request, _ = _verify_request(root, task_id)
        with _task_lock(tasks_root, _key_prefix(initial_request["key"])):
            directory, request, _ = _verify_request(root, task_id)
            data = _read_file(Path(image).expanduser(), _MAX_IMAGE_BYTES)
            image_format, width, height = _image_info(data)
            digest = hashlib.sha256(data).hexdigest()
            region = None
            if main_region is not None:
                if request["kind"] not in {"scene", "prop"}:
                    raise ValueError("Main region is only supported for scene and prop tasks")
                region = _main_region(main_region, data)
            existing, _ = _verify_result(directory, request)
            if existing:
                if existing["sha256"] != digest:
                    raise ValueError("A different result is already recorded; create a new run")
                if region is not None and existing.get("main_region") != region:
                    raise ValueError(
                        "A different main region is already recorded; create a new run"
                    )
                return _describe(root, task_id)
            results = _within(directory, "results")
            results.mkdir(exist_ok=True)
            _within(directory, "results", must_exist=True)
            path = _within(results, digest + _IMAGE_EXT[image_format])
            if path.exists():
                if _read_file(path, _MAX_IMAGE_BYTES) != data:
                    raise ValueError("Image task result content conflicts with existing file")
            else:
                _write_bytes(path, data)
            result = {
                "schema_version": 1,
                "status": "completed",
                "task_sha256": request["task_sha256"],
                "path": "results/" + path.name,
                "sha256": digest,
                "format": image_format,
                "width": width,
                "height": height,
                "notes": notes.strip(),
                "review_accepted": True,
            }
            if region is not None:
                result["main_region"] = region
            _within(directory, "result.json")
            write_json(directory / "result.json", result)
            return _describe(root, task_id)
